const QUESTIONS = [{"q":"Halfway to a client's home, you realize you left your glass cleaner in the office. What's your move?","opts":["Inform the client immediately and check if another tool can be used safely.","Try to manage with the tools available without telling the client.","Borrow a tool from the client's private supplies without asking.","Skip the task that needs that tool and say nothing."],"correct":0,"cat":"Safety","scored":true,"id":0},{"q":"While cleaning a private room, you accidentally chip a small decorative item. The client is in another part of the house. What is your first step?","opts":["Clean the area and check if the damage can be fixed before reporting it.","Try to manage with the tools available without telling the client.","Assume the client already knows about it.","Immediately find the client, apologize, and explain what happened."],"correct":3,"cat":"Honesty","scored":true,"id":1},{"q":"You notice a small jewelry box left open on a dresser you need to dust. What do you do?","opts":["Close the box yourself to ensure the items are safe.","Dust around the box without touching it.","Politely ask the client if they would like you to move the items or skip that area.","Carefully move the jewelry to dust the box."],"correct":2,"cat":"Professionalism","scored":true,"id":2},{"q":"If you finish your cleaning tasks earlier than the scheduled time, what is the best approach?","opts":["Work extra hours without telling anyone and ask the client for more money at the end.","Ask the client if there is any other small task they would like you to focus on with the remaining time.","Check the house one last time to ensure everything is perfect.","Pack your equipment and wait in your car until the scheduled time ends."],"correct":1,"cat":"Time","scored":true,"id":3},{"q":"A client points out a small area in the kitchen that was missed during cleaning. How do you respond?","opts":["Thank them for pointing it out and clean it immediately.","Apologize and promise to focus more on that area next time.","Explain that you were following a specific checklist.","Mention that the missed area was already very stained."],"correct":0,"cat":"Communication","scored":true,"id":4},{"q":"A client asks you to clean balcony glass on a high floor using a tall step ladder, against your safety training. What do you do?","opts":["Follow the client's instructions exactly to keep them happy.","Perform the task but do it as quickly as possible to avoid risk.","Leave the home immediately and call the office.","Politely explain the safety policy and offer a safer alternative to achieve the same result."],"correct":3,"cat":"Safety","scored":true,"id":5},{"q":"A client becomes frustrated or raises their voice about a service issue. What is your reaction?","opts":["Ignore the client until they finish talking and then continue cleaning.","Leave the home immediately and call the office.","Listen calmly, apologize for the frustration, and try to resolve the issue immediately.","Defend your work and explain why they are wrong."],"correct":2,"cat":"Communication","scored":true,"id":6},{"q":"If you are assigned multiple rooms at a large home like a villa, how do you prioritize?","opts":["Start with the rooms that the client uses most frequently.","Ask the client which area they would like you to finish first.","Start with the room that looks the dirtiest.","Start with the easiest tasks to make quick progress."],"correct":1,"cat":"Time","scored":true,"id":7},{"q":"You are cleaning a home alone and realize one room is much dirtier than expected, putting you behind schedule. What do you do?","opts":["Immediately contact the client or helpcenter to explain the situation and ask for more time or instructions, then focus on the high-priority areas.","Clean that room quickly and skip the smaller details so you can finish the rest of the house on time.","Work faster and lower the quality of cleaning to finish on time.","Continue at your normal pace and leave the last few tasks unfinished when your time is up."],"correct":0,"cat":"Time","scored":true,"id":8},{"q":"You feel the time allocated for a specific home is not enough to complete all tasks to a high standard. What do you do?","opts":["Work faster and lower the quality of cleaning to finish on time.","Clean that room quickly and skip the smaller details so you can finish the rest of the house on time.","Do it for free to be nice.","Focus on the most important areas and inform the client/office about the time constraint."],"correct":3,"cat":"Time","scored":true,"id":9},{"q":"What type of work environment do you prefer?","opts":["A place where work changes often and is flexible.","A place where work is steady and predictable.","A place where tasks are clearly assigned and repetitive.","A place where I can work independently with little supervision."],"correct":2,"cat":"Attitude","scored":true,"id":10},{"q":"Which statement best describes your approach to training?","opts":["I prefer completing work as quickly as possible.","I take training seriously and follow it even when no one is watching.","I follow the rules only when I am being checked.","I like finding my own way of doing things regardless of the manual."],"correct":1,"cat":"Attitude","scored":true,"id":11},{"q":"If you were offered a higher pay elsewhere, what would you consider?","opts":["Compare the long-term benefits and job stability of both roles.","Ask your current client if they will pay you more to stay.","Leave your current job immediately for the higher pay.","Take the other job but keep the current one as a backup without telling the company."],"correct":0,"cat":"Attitude","scored":true,"id":12},{"q":"How long would you prefer to stay as a Part Time Cleaner role?","opts":["For the long term to build strong client relationships.","Until I have enough experience for a different field.","Until I find a better opportunity.","As long as the work environment remains good."],"correct":0,"cat":"Attitude","scored":true,"id":13},{"q":"When starting a job at a new client's house, what matters most to you?","opts":["Finishing the tasks as quickly as possible.","Using the least amount of cleaning supplies.","Understanding the specific needs of the client.","Completing the job independently without asking questions."],"correct":2,"cat":"Professionalism","scored":true,"id":14},{"q":"You notice a small leak under the kitchen sink while cleaning. The client is not home. What do you do?","opts":["Try to cover it up with furniture.","Put a towel down and report it to the client immediately.","Try to tighten the pipes yourself.","Assume the client already knows about it."],"correct":1,"cat":"Honesty","scored":true,"id":15},{"q":"If a client asks you to perform a task that is NOT on your booking, do you:","opts":["Politely inform them it's not on the list but offer to check with the office about adding it.","Do it for free to be nice.","Tell them you don't have time.","Do it but ask the client for a cash tip in exchange."],"correct":0,"cat":"Professionalism","scored":true,"id":16},{"q":"The client's dog or cat is making it difficult for you to clean a specific room safely. How do you handle this?","opts":["Try to shoo the dog/cat out of the room yourself.","Wait until the dog/cat moves on its own, even if it delays the job.","Skip that room and don't tell the client.","Politely ask the client if they can secure the dog/cat while you clean that area."],"correct":3,"cat":"Communication","scored":true,"id":17},{"q":"True or False: An experienced cleaner can safely skip steps to save time without losing quality.","opts":["False — high-quality cleaning requires consistent time and attention to detail.","True."],"correct":0,"cat":"Attitude","scored":true,"id":18},{"q":"If you make a mistake you can't fix (like staining a rug or carpet), what is the best response?","opts":["Mention that the missed area was already very stained.","Tell the client immediately and offer to call the office to handle the claim.","Clean the rest of the house exceptionally well so they won't be mad about the stain.","Try to cover it up with furniture."],"correct":1,"cat":"Honesty","scored":true,"id":19},{"q":"A client offers to pay you directly in cash to skip the agency and save on fees. What do you do?","opts":["Politely decline and explain that all work must go through the company.","Agree, since it benefits both of you financially.","Take the offer but still report the booking as usual through the agency.","Tell the client you'll think about it and discuss it with them later."],"correct":0,"cat":"Honesty","scored":true,"id":20},{"q":"While cleaning, you find a banknote that must have dropped on the floor. What do you do?","opts":["Pocket it since it's a small amount and unlikely to be missed.","Leave it exactly where it is and say nothing.","Ask a coworker what they would do before deciding.","Leave it in plain view and inform the client as soon as possible."],"correct":3,"cat":"Honesty","scored":true,"id":21},{"q":"No one from the office or the client is checking on you during a job. Does this change how you work?","opts":["Yes — I focus only on what the client is likely to check.","Yes — I prioritize finishing fast since there's no supervision.","No — I follow the same standard and procedures whether or not anyone is watching.","Somewhat — I relax a little since no one will know."],"correct":2,"cat":"Attitude","scored":true,"id":22},{"q":"You find a cleaning chemical bottle with no label at a client's home and you're unsure what it is. What do you do?","opts":["Use it anyway since it looks similar to a product you know.","Ask the client what it is before using it, or avoid using it and use your own supplies.","Mix it with your own chemicals to test it.","Throw it away without asking."],"correct":1,"cat":"Safety","scored":true,"id":23},{"q":"While vacuuming, you notice the cord is frayed and slightly exposed. What should you do?","opts":["Continue using it carefully since it still works.","Stop using it immediately and report the equipment issue to the office.","Wrap it in tape yourself and keep using it.","Use it only in dry areas."],"correct":1,"cat":"Safety","scored":true,"id":24},{"q":"You need to clean a high shelf but there's no stable ladder available, only a wobbly chair. What's the safest action?","opts":["Use the wobbly chair carefully while holding onto something.","Use an extension duster or pole to reach safely from the ground instead of climbing.","Ask a family member to hold the chair steady while you climb.","Skip that shelf and say nothing."],"correct":1,"cat":"Safety","scored":true,"id":25},{"q":"You're asked to move a heavy piece of furniture alone to clean behind it, and it feels too heavy to lift safely. What do you do?","opts":["Push through and lift it anyway to finish quickly.","Ask the client if you can clean around it instead, or request help.","Drag it forcefully across the floor.","Skip the task without mentioning it."],"correct":1,"cat":"Safety","scored":true,"id":26},{"q":"Which of the following is the safest way to handle cleaning chemicals?","opts":["Mix different chemicals together for a stronger effect.","Always read labels and never mix chemicals unless instructed.","Store all chemicals together for convenience.","Use as much chemical as possible for the best results."],"correct":1,"cat":"Safety","scored":true,"id":27},{"q":"You notice a loose electrical socket near a wet area you need to clean. What is the right approach?","opts":["Clean the area carefully avoiding the socket and inform the client/office.","Clean it as normal since sockets are usually fine.","Try to fix the socket yourself.","Cover the socket with a wet cloth and continue cleaning."],"correct":0,"cat":"Safety","scored":true,"id":28},{"q":"A client asks you to clean windows from the outside on an upper floor without any safety equipment. What should you do?","opts":["Do it carefully while holding onto the window frame.","Politely decline and explain this is outside safety policy, offering to clean from inside instead.","Do it quickly since it's just one time.","Ask a family member to hold your legs while you lean out."],"correct":1,"cat":"Safety","scored":true,"id":29},{"q":"Before starting any cleaning job, what is the best first step regarding safety?","opts":["Start cleaning immediately to save time.","Quickly check the work area for visible hazards like wet floors or exposed wires.","Ask the client for tea first.","Assume the space is safe since it's a home."],"correct":1,"cat":"Safety","scored":true,"id":30},{"q":"You accidentally spill a cleaning liquid on a tiled floor, making it slippery. What do you do first?","opts":["Continue cleaning and clean the spill later.","Wipe it up immediately and warn anyone nearby about the slippery area.","Leave it since it will dry on its own.","Cover it with a rug so no one notices."],"correct":1,"cat":"Safety","scored":true,"id":31},{"q":"If you feel unwell (dizzy, nauseous) after using a strong cleaning chemical, what should you do?","opts":["Push through and finish the job.","Stop, move to fresh air, and inform the client and office immediately.","Drink water and continue with the same chemical.","Switch to a different room without saying anything."],"correct":1,"cat":"Safety","scored":true,"id":32},{"q":"You accidentally break a client's item and no one saw it happen. What is the right thing to do?","opts":["Say nothing since no one saw.","Hide the broken pieces.","Inform the client honestly and report it to the office.","Quietly replace it without telling anyone."],"correct":2,"cat":"Honesty","scored":true,"id":33},{"q":"A client leaves a generous tip in cash on the table without saying anything. What do you do?","opts":["Assume it's meant for you and take it without mentioning it.","Confirm with the client whether it's meant for you before taking it.","Leave it there and don't mention it.","Take half and leave half."],"correct":1,"cat":"Honesty","scored":true,"id":34},{"q":"You finish a job in less time than booked. What do you do?","opts":["Leave immediately without informing anyone.","Inform the client/office of the actual time taken, honestly.","Stay idle to make it look like you used the full time.","Ask the client to sign off on the full booked time even though you finished early."],"correct":1,"cat":"Honesty","scored":true,"id":35},{"q":"A coworker asks you to clock them in even though they haven't arrived yet. What do you do?","opts":["Do it since it's a small favor.","Decline and explain you can't do that.","Do it but ask them to return the favor later.","Ignore the request without saying anything."],"correct":1,"cat":"Honesty","scored":true,"id":36},{"q":"You notice a small amount of a client's food or drink seems to have gone missing, but you didn't take it. What's the best approach?","opts":["Say nothing and hope it's not noticed.","Mention proactively that you noticed something seems different, staying transparent.","Blame another cleaner.","Avoid that client's home in future."],"correct":1,"cat":"Honesty","scored":true,"id":37},{"q":"If you accidentally use more of the client's cleaning supplies than usual, what should you do?","opts":["Say nothing since it's a small amount.","Mention it to the client so they're aware for restocking.","Refill the bottle with water to hide it.","Bring your own next time without saying why."],"correct":1,"cat":"Honesty","scored":true,"id":38},{"q":"A client offers to write you a fake positive review in exchange for skipping part of the cleaning checklist. What do you do?","opts":["Accept since it benefits both.","Politely decline and complete the checklist as required.","Accept but still do the full job anyway.","Report the client to the police."],"correct":1,"cat":"Honesty","scored":true,"id":39},{"q":"You find a used credit card or ID card while cleaning. What is the right action?","opts":["Leave it in plain view and inform the client.","Move it somewhere \"safer\" without telling anyone.","Take a photo of it out of curiosity.","Ignore it completely."],"correct":0,"cat":"Honesty","scored":true,"id":40},{"q":"If you're asked about your past work experience, what's the right approach?","opts":["Exaggerate your experience to sound more qualified.","Answer honestly about your actual experience and skills.","Avoid answering the question.","Say whatever you think they want to hear."],"correct":1,"cat":"Honesty","scored":true,"id":41},{"q":"You realize you made an error filling out a job or attendance report. What should you do?","opts":["Leave it as is since it's minor.","Correct it honestly and inform the office if needed.","Ask a coworker to cover for you.","Delete the report entirely."],"correct":1,"cat":"Honesty","scored":true,"id":42},{"q":"A client speaks a language you're not fluent in. How do you ensure clear communication about tasks?","opts":["Guess what they want and proceed.","Use simple words, gestures, or a translation app, and confirm understanding before starting.","Avoid speaking to them at all.","Only do the tasks you're sure about and ignore the rest."],"correct":1,"cat":"Communication","scored":true,"id":43},{"q":"A client wants to add extra rooms to the cleaning job that weren't part of the original booking. What's the best response?","opts":["Refuse completely and leave.","Explain the current booking scope and offer to check with the office about extending it.","Do it for free to avoid conflict.","Do it but charge the client directly in cash."],"correct":1,"cat":"Communication","scored":true,"id":44},{"q":"Before starting a job at a new home, what's a good first step with the client?","opts":["Start cleaning immediately without talking to them.","Briefly confirm the scope of work and any specific preferences.","Ask for a tip upfront.","Wait for the client to give detailed instructions on every single item."],"correct":1,"cat":"Communication","scored":true,"id":45},{"q":"A client gives vague instructions like \"just clean everything.\" What should you do?","opts":["Guess what \"everything\" means and clean a random selection.","Politely ask clarifying questions or follow the standard checklist and confirm priorities.","Only clean the areas that look dirtiest to you.","Skip unclear areas entirely."],"correct":1,"cat":"Communication","scored":true,"id":46},{"q":"If a client is not home during the scheduled cleaning and you have questions mid-task, what should you do?","opts":["Guess and proceed however you think is best without any contact.","Try to reach the client by call/message, or contact the office if unavailable.","Stop working until they return.","Skip the parts you're unsure about and leave."],"correct":1,"cat":"Communication","scored":true,"id":47},{"q":"A client compliments your work and asks for your personal phone number to book you directly outside the app. What do you do?","opts":["Give your number since it's flattering.","Politely decline and explain all bookings must go through the company.","Give a fake number to avoid conflict.","Agree but ask them to keep it secret."],"correct":1,"cat":"Communication","scored":true,"id":48},{"q":"How should you communicate if you're going to be late to a scheduled job?","opts":["Just arrive late without saying anything.","Inform the client and/or office as early as possible.","Cancel the job without notice.","Ask a friend to go in your place without telling the office."],"correct":1,"cat":"Communication","scored":true,"id":49},{"q":"A client is unhappy but you believe the work was actually done well. What's the best response?","opts":["Argue your case firmly until they agree.","Listen to their concerns respectfully and address them, even if you disagree internally.","Ignore their feedback since you know you did well.","Tell them to lower their expectations next time."],"correct":1,"cat":"Communication","scored":true,"id":50},{"q":"At the end of a job, what's a good final step with the client?","opts":["Leave immediately once the timer ends.","Do a quick walkthrough with the client to confirm everything meets expectations.","Ask for a tip before they can review the work.","Rush them to sign off quickly."],"correct":1,"cat":"Communication","scored":true,"id":51},{"q":"If a client asks you a question you don't know the answer to (e.g. about pricing or policies), what should you do?","opts":["Make up an answer so you seem knowledgeable.","Let them know you're not sure and offer to check with the office.","Ignore the question.","Tell them to figure it out themselves."],"correct":1,"cat":"Communication","scored":true,"id":52},{"q":"You have four tasks and only enough time for three. How do you decide what to skip?","opts":["Skip whatever is hardest.","Prioritize based on the client's stated preferences or the most impactful areas, and inform them of the trade-off.","Do a little of each task instead of completing any fully.","Randomly pick which to skip."],"correct":1,"cat":"Time","scored":true,"id":53},{"q":"You arrive at a job and realize the space is much larger than expected for the time booked. What's your first move?","opts":["Rush through everything superficially.","Inform the client/office about the mismatch and prioritize accordingly.","Do only half the home and leave.","Extend the job on your own without informing anyone."],"correct":1,"cat":"Time","scored":true,"id":54},{"q":"Which is the best way to manage your time across multiple bookings in a day?","opts":["Rush every job to leave buffer time for personal breaks.","Plan realistic timing per job factoring in travel, and communicate proactively if running behind.","Take jobs in whatever order is most convenient for you, ignoring booked times.","Skip the last job if you're tired."],"correct":1,"cat":"Time","scored":true,"id":55},{"q":"A task isn't part of your standard checklist but would take just one extra minute and the client asks nicely. What do you do?","opts":["Always refuse strictly.","Use reasonable judgment — a quick goodwill task is fine, but recurring extra requests should go through the office.","Do unlimited extra tasks for free every time.","Charge the client cash directly for it."],"correct":1,"cat":"Time","scored":true,"id":56},{"q":"If the client's home requires deep cleaning but you were booked for a standard clean, what should you do?","opts":["Attempt the deep clean anyway and go over time without telling anyone.","Complete the standard clean well and inform the client/office that a deep clean would need a separate booking.","Refuse to do any cleaning at all.","Rush the standard clean to also start deep cleaning."],"correct":1,"cat":"Time","scored":true,"id":57},{"q":"How should you handle a day with back-to-back bookings and unexpected traffic delays?","opts":["Skip a booking without informing anyone.","Notify the office/clients affected as soon as you know you'll be delayed.","Rush unsafely to make up time.","Do a lower quality job at each stop to save time."],"correct":1,"cat":"Time","scored":true,"id":58},{"q":"You're asked to clean a very cluttered room. What's the best approach to prioritize?","opts":["Skip the room since it will take too long.","Ask the client how they'd like clutter handled, then clean efficiently around their preference.","Move all clutter into another room without asking.","Throw away anything that looks like trash without checking."],"correct":1,"cat":"Time","scored":true,"id":59},{"q":"If you complete your checklist with 20 minutes remaining, what's the ideal use of that time?","opts":["Leave early since the checklist is done.","Do a final quality check or ask the client if anything else needs attention.","Sit and wait without checking anything.","Start a task not related to the booking without asking."],"correct":1,"cat":"Time","scored":true,"id":60},{"q":"A client invites you to eat with their family during a break. What's an appropriate response?","opts":["Accept enthusiastically and take a long break.","Politely thank them and decline or keep it brief, staying professional and on schedule.","Ignore the invitation completely without acknowledgment.","Accept and ask for extra food to take home."],"correct":1,"cat":"Professionalism","scored":true,"id":61},{"q":"What is the most appropriate way to dress for a cleaning job?","opts":["Whatever is most comfortable regardless of guidelines.","According to the company's uniform/dress code guidelines, clean and presentable.","Formal business attire.","Whatever the client prefers you to wear."],"correct":1,"cat":"Professionalism","scored":true,"id":62},{"q":"A client asks personal questions about your family, income, or living situation. How should you respond?","opts":["Answer every question in full detail.","Keep responses polite but brief, redirecting focus back to the job.","Refuse to speak at all.","Ask the client equally personal questions back."],"correct":1,"cat":"Professionalism","scored":true,"id":63},{"q":"You notice the client's home has sensitive documents or personal items in view while you clean. What's the professional approach?","opts":["Read through them out of curiosity.","Avoid touching or looking through personal items beyond what's needed to clean.","Take photos for your own records.","Rearrange them to be tidier without asking."],"correct":1,"cat":"Professionalism","scored":true,"id":64},{"q":"A client asks you to babysit their child while they step out, which is outside your job scope. What do you do?","opts":["Agree since it seems like a small favor.","Politely explain this isn't part of your role and isn't covered by company policy.","Agree but ask for extra cash.","Refuse rudely and leave."],"correct":1,"cat":"Professionalism","scored":true,"id":65},{"q":"What should you do if you accidentally see something private (e.g., an open laptop or phone) while cleaning?","opts":["Look closer out of curiosity.","Avert your attention and continue your task without engaging with it.","Mention what you saw to the client.","Take a photo."],"correct":1,"cat":"Professionalism","scored":true,"id":66},{"q":"How should you handle using the client's bathroom or personal facilities during a job?","opts":["Use freely without asking.","Ask the client's permission first, if you need to use it.","Avoid it even if urgently needed.","Use it only when the client isn't home, without asking."],"correct":1,"cat":"Professionalism","scored":true,"id":67},{"q":"A client wants to take a photo or video of you for social media without asking beforehand. What's appropriate?","opts":["Agree automatically since it's their home.","Ask them to confirm your consent first — it's fine to decline if uncomfortable.","Pose for extra photos to be nice.","Ignore the situation and keep working."],"correct":1,"cat":"Professionalism","scored":true,"id":68},{"q":"If a client makes you uncomfortable with inappropriate behavior or comments, what should you do?","opts":["Stay quiet and continue working.","End the interaction professionally and report it to the office as soon as possible.","Respond with equally inappropriate comments.","Avoid that client without telling the office why."],"correct":1,"cat":"Professionalism","scored":true,"id":69},{"q":"What's the best way to handle bringing your phone to a job?","opts":["Use it freely throughout the job for calls and social media.","Keep it for emergencies/work communication and avoid personal use during work hours.","Leave it at home entirely, even for emergencies.","Use it only when the client isn't watching."],"correct":1,"cat":"Professionalism","scored":true,"id":70},{"q":"You use the wrong cleaning product on a delicate surface and notice discoloration. What do you do?","opts":["Try to cover the area with furniture or décor.","Stop using the product, inform the client immediately, and report it to the office.","Use more product hoping it fixes itself.","Say nothing and hope it's not noticed."],"correct":1,"cat":"Honesty","scored":true,"id":71},{"q":"You knock over and break a small decorative item while dusting. No one is around. What's the right action?","opts":["Throw away the pieces so no one notices it's missing.","Keep the pieces, inform the client honestly, and report to the office for the claims process.","Replace it with a similar item you buy yourself, without mentioning it.","Rearrange other items to hide the gap."],"correct":1,"cat":"Honesty","scored":true,"id":72},{"q":"You realize partway through a job that you forgot to bring an essential piece of equipment. What's best?","opts":["Skip the tasks needing that equipment and say nothing.","Inform the client/office promptly and find the best available alternative.","Ask the client to buy new equipment for you.","Leave the job without explanation."],"correct":1,"cat":"Honesty","scored":true,"id":73},{"q":"You accidentally lock yourself out of a room or area you needed to clean. What do you do?","opts":["Force the door open.","Inform the client calmly and ask for assistance, or skip with explanation.","Climb through a window.","Leave without mentioning the room was skipped."],"correct":1,"cat":"Honesty","scored":true,"id":74},{"q":"A client claims something is missing after your visit, but you're certain you didn't take anything. What's the right response?","opts":["Get defensive and argue.","Stay calm, cooperate fully, and report the situation to the office immediately.","Refuse to discuss it and leave.","Offer to pay for it immediately just to end the conversation."],"correct":1,"cat":"Honesty","scored":true,"id":75},{"q":"You spill a small amount of cleaning liquid on a client's rug and it leaves a mark. What's the right next step?","opts":["Flip the rug over so the mark isn't visible.","Blot it immediately if safe to do so, then inform the client and report it.","Say nothing since it's a small mark.","Move the rug to another room."],"correct":1,"cat":"Honesty","scored":true,"id":76},{"q":"You realize after leaving a job that you may have left a cabinet or door unlocked. What should you do?","opts":["Ignore it since the job is already done.","Contact the client or office immediately to alert them.","Wait until your next visit to check.","Assume it's fine since nothing was reported."],"correct":1,"cat":"Honesty","scored":true,"id":77},{"q":"How do you typically handle repetitive daily tasks over a long period?","opts":["Get careless as tasks become familiar.","Maintain the same consistent quality and attention every time.","Do the minimum required.","Look for shortcuts even if they lower quality."],"correct":1,"cat":"Attitude","scored":true,"id":78},{"q":"If you're asked to learn a new cleaning method or tool, how do you respond?","opts":["Resist since your current method works fine.","Stay open to learning and apply new methods as trained.","Learn it but continue using your old method anyway.","Only learn it if paid extra."],"correct":1,"cat":"Attitude","scored":true,"id":79},{"q":"What best describes reliable attendance for this role?","opts":["Show up when convenient.","Arrive on time consistently and inform in advance if unable to attend.","Attend most days but skip without notice occasionally.","Attendance isn't very important as long as work gets done eventually."],"correct":1,"cat":"Attitude","scored":true,"id":80},{"q":"How do you handle receiving constructive criticism from a supervisor?","opts":["Get defensive and argue.","Listen, reflect, and use it to improve.","Ignore it since you know your own work best.","Take it personally and consider quitting."],"correct":1,"cat":"Attitude","scored":true,"id":81},{"q":"If a coworker isn't pulling their weight on a shared job, what's the best approach?","opts":["Do all the extra work silently and say nothing.","Communicate with them directly first, and involve the office if it continues.","Complain to the client about the coworker.","Match their low effort so it's \"fair.\""],"correct":1,"cat":"Teamwork","scored":true,"id":82},{"q":"What's the best mindset when starting a new job assignment each day?","opts":["Treat every home with the same care and professionalism regardless of size or client.","Put in less effort for smaller or lower-paying jobs.","Only try hard when you think you're being evaluated.","Do the minimum to avoid complaints."],"correct":0,"cat":"Attitude","scored":true,"id":83},{"q":"How should you handle a personal problem affecting your mood before a job?","opts":["Let it affect how you interact with the client.","Do your best to stay professional and composed with the client, and seek support if needed.","Cancel the job without notice.","Vent about it to the client."],"correct":1,"cat":"Attitude","scored":true,"id":84},{"q":"What is a sign of strong long-term potential in this role?","opts":["Doing just enough to avoid complaints.","Consistency, honesty, and willingness to build client trust over time.","Trying to get the highest-paying clients only.","Avoiding feedback to prevent conflict."],"correct":1,"cat":"Attitude","scored":true,"id":85},{"q":"What is the correct way to store cleaning chemicals you bring to a job?","opts":["Leave them open on a counter for easy access.","Keep them sealed, labeled, and out of reach of children/pets when not in use.","Mix a few together into one bottle to save space.","Leave them wherever you finish using them."],"correct":1,"cat":"Safety","scored":true,"id":86},{"q":"Before using a new cleaning product on a client's furniture, what should you do?","opts":["Use it directly on the full surface.","Test it on a small, inconspicuous area first if unsure of compatibility.","Ask the client to test it themselves.","Avoid using it and skip the surface entirely."],"correct":1,"cat":"Safety","scored":true,"id":87},{"q":"How should you handle a client's clothing or laundry if it's part of the job?","opts":["Sort and handle it however is fastest.","Follow care labels and the client's instructions carefully.","Wash everything on the same setting regardless of fabric.","Skip laundry if it seems complicated."],"correct":1,"cat":"Professionalism","scored":true,"id":88},{"q":"If you need to move personal or fragile items to clean a surface, what's best practice?","opts":["Move quickly without much care to save time.","Handle items carefully and return them to their original position.","Leave the items in a random new spot.","Avoid cleaning under/around them at all."],"correct":1,"cat":"Professionalism","scored":true,"id":89},{"q":"What should you do with used cleaning cloths or mop heads between different rooms (e.g., bathroom vs kitchen)?","opts":["Use the same cloth everywhere to save time.","Use separate or properly cleaned cloths for different areas to avoid cross-contamination.","Rinse briefly in the toilet if convenient.","It doesn't matter as long as it looks clean."],"correct":1,"cat":"Safety","scored":true,"id":90},{"q":"How should trash/garbage be handled at the end of a job?","opts":["Leave bags wherever is convenient.","Dispose of it properly according to the client's preferred method/location.","Leave full bins for the client to empty even if instructed otherwise.","Take the client's trash with you without asking."],"correct":1,"cat":"Professionalism","scored":true,"id":91},{"q":"If you notice mold or a pest issue while cleaning, what should you do?","opts":["Ignore it since it's not your job to fix.","Inform the client so they're aware, and note it for the office if relevant.","Try to treat it yourself with random chemicals.","Cover the area so it's not visible."],"correct":1,"cat":"Communication","scored":true,"id":92},{"q":"What is the best approach to cleaning around a client's electronics (TV, computer, etc.)?","opts":["Spray cleaner directly on the screens.","Use appropriate, dry or lightly damp methods suited for electronics, avoiding direct liquid.","Avoid the area entirely, even if dusty.","Unplug everything without asking first."],"correct":1,"cat":"Safety","scored":true,"id":93},{"q":"If you're unsure whether a task is within your job scope, what should you do?","opts":["Just do it to avoid conflict.","Check with the office/supervisor if unsure before proceeding.","Refuse without explanation.","Ask the client to clarify the company's policy."],"correct":1,"cat":"Teamwork","scored":true,"id":94},{"q":"Two cleaners are assigned to the same large home. How should tasks be divided?","opts":["Whoever is faster does more, without discussion.","Discuss and divide tasks clearly at the start to avoid overlap or gaps.","Work on whatever you personally prefer.","Compete to see who finishes first."],"correct":1,"cat":"Teamwork","scored":true,"id":95},{"q":"If you disagree with a decision made by your supervisor or office, what's the appropriate way to handle it?","opts":["Ignore the decision and do it your own way.","Raise your concern respectfully through proper channels.","Complain to clients about the office.","Comply outwardly but intentionally do a poor job."],"correct":1,"cat":"Teamwork","scored":true,"id":96},{"q":"If you witness a coworker doing something unsafe or against policy, what should you do?","opts":["Ignore it since it's not your responsibility.","Address it if appropriate and report it to the office if serious.","Join in since everyone else does it.","Post about it publicly online."],"correct":1,"cat":"Teamwork","scored":true,"id":97},{"q":"How should you request time off or report unavailability for upcoming bookings?","opts":["Simply don't show up.","Notify the office as early as possible through the proper process.","Ask a coworker to inform the office on your behalf without confirming.","Tell the client directly and skip informing the office."],"correct":1,"cat":"Teamwork","scored":true,"id":98},{"q":"If the office asks you to help cover an urgent last-minute job, how should you respond?","opts":["Always refuse regardless of availability.","Let them know honestly whether you're available, without pressure to overcommit.","Agree even if it means missing a prior commitment without telling anyone.","Ignore the request."],"correct":1,"cat":"Teamwork","scored":true,"id":99},{"q":"You are cleaning a wooden dining table. Which cloth is best to avoid scratching it?","opts":["A rough scrubbing pad","A soft microfiber cloth","Steel wool","Any old cloth"],"correct":1,"cat":"Skill","scored":true,"id":100},{"q":"What is the correct order to clean a room for the best result?","opts":["Clean the floor first, then dust the surfaces","Dust and wipe surfaces first, then clean the floor last","Clean windows only","Order does not matter"],"correct":1,"cat":"Skill","scored":true,"id":101},{"q":"Which method is best for cleaning glass and mirrors without leaving streaks?","opts":["A wet cloth with only water","A lint-free cloth or newspaper with glass cleaner","A rough sponge","A cloth with cooking oil"],"correct":1,"cat":"Skill","scored":true,"id":102},{"q":"When mopping a floor, what is the best way to make sure it is safe and dries properly?","opts":["Leave large puddles of water on the floor","Use a well wrung mop and clean in small sections","Pour extra water for a deeper clean","Mop only the middle of the room"],"correct":1,"cat":"Skill","scored":true,"id":103},{"q":"Why do you want to work as a cleaner with Urban Company?","opts":["To have a stable and honest way to earn a good income","I have no other option right now","A friend told me to apply","I am not sure yet"],"correct":0,"cat":"Intent","scored":true,"id":104},{"q":"If you were offered free training on new cleaning tools and techniques, how would you feel?","opts":["I would attend and try to learn as much as possible","I would attend only if it is compulsory","I would skip it since I already know cleaning","I would attend but not pay much attention"],"correct":0,"cat":"Intent","scored":true,"id":105},{"q":"How do you feel about being corrected by a supervisor if your work needs improvement?","opts":["I would feel upset and stop trying","I would listen carefully and try to improve my work","I would ignore the feedback","I would argue that my way is better"],"correct":1,"cat":"Intent","scored":true,"id":106},{"q":"If a job requires slightly more physical effort than usual, what is your attitude?","opts":["I will do my best to complete it properly","I will do it half-heartedly","I will refuse and ask for a different job","I will complain to the client"],"correct":0,"cat":"Intent","scored":true,"id":107},{"q":"You reach a client's home and they are not answering the door or phone. What should you do?","opts":["Leave immediately without informing anyone","Wait a reasonable time, try contacting them again, and inform the office if there is still no response","Try to enter through another door","Leave and never follow up"],"correct":1,"cat":"SituationHandling","scored":true,"id":108},{"q":"A client asks you to clean using a chemical you have never used before, with no instructions. What is the safest step?","opts":["Use it the same way as a similar chemical","Check the label or ask the client before using it, or use your own trusted supplies","Mix it with your own chemicals","Avoid the task without telling anyone"],"correct":1,"cat":"SituationHandling","scored":true,"id":109},{"q":"What should you always check before using an electrical cleaning appliance like a vacuum cleaner?","opts":["The color of the appliance","That the cord and plug are not damaged","How heavy it is","Nothing, just plug it in and use it"],"correct":1,"cat":"Skill","scored":true,"id":110},{"q":"What is the correct way to clean a bathroom so germs do not spread to other areas?","opts":["Use the same cloth for the toilet and the sink","Clean from the cleanest areas to the dirtiest, using separate cloths where possible","Start with the toilet and use that same cloth everywhere else","Order does not matter"],"correct":1,"cat":"Skill","scored":true,"id":111},{"q":"While working, you accidentally make a loud noise that seems to disturb someone resting in another room. What should you do?","opts":["Ignore it and continue as normal","Politely apologize and be more careful going forward","Stop working completely without telling anyone","Blame the equipment"],"correct":1,"cat":"SituationHandling","scored":true,"id":112},{"q":"How should you greet a client when you arrive for a job?","opts":["Walk in directly without greeting","Greet them politely, introduce yourself, and confirm you are there for the scheduled job","Wait silently until they notice you","Only greet them if they greet you first"],"correct":1,"cat":"SituationHandling","scored":true,"id":113},{"q":"What would you do if you were assigned a job farther from your home than usual?","opts":["Refuse the job immediately","Accept it if reasonably possible, and inform the office if there is a genuine issue","Accept the job but arrive whenever convenient","Ignore the assignment"],"correct":1,"cat":"Intent","scored":true,"id":114},{"q":"You are unsure how to safely remove a specific tough stain. What is the best action?","opts":["Try random products until one works","Ask a supervisor or refer to your training material before attempting it","Ignore the stain completely","Use the strongest chemical you have without checking"],"correct":1,"cat":"SituationHandling","scored":true,"id":115},{"q":"What is an important habit for good hygiene when cleaning multiple homes in one day?","opts":["Washing your hands and using clean supplies between homes","Using the same gloves and cloths at every home","Hygiene does not matter between homes","Only washing hands at the end of the day"],"correct":0,"cat":"Skill","scored":true,"id":116},{"q":"If you feel tired midway through a job, what is the right approach?","opts":["Rush through the remaining tasks carelessly","Take a short breather if truly needed, then continue with the same quality of work","Stop the job and leave","Ask the client to finish it themselves"],"correct":1,"cat":"Intent","scored":true,"id":117},{"q":"How willing are you to follow a standard cleaning checklist even if it's different from how you clean at home?","opts":["Very willing, I will follow the training and checklist provided","Only if it is easier than my own way","I prefer to always do it my own way","I would follow it only when someone is watching"],"correct":0,"cat":"Intent","scored":true,"id":118},{"q":"You notice a coworker is not following proper hygiene practices, which could affect the client's trust. What should you do?","opts":["Ignore it since it is not your responsibility","Politely mention it to them, and inform the office if it continues","Complain to the client directly about your coworker","Do the same to match them"],"correct":1,"cat":"SituationHandling","scored":true,"id":119},{"q":"You need to clean a very dirty house, but you only have 2 hours instead of the usual 4. What should you do?","opts":["Skip the areas that take too long and only clean what looks easy.","Quickly check which areas matter most to the customer and clean those thoroughly first, leaving less important spots for last.","Try to clean everything at the same speed and finish whatever you can in order.","Call the customer and ask them to give you more time before you start."],"correct":1,"cat":"Skill","scored":true,"id":120},{"q":"While mopping, the floor still looks a bit dull after you clean it with your usual cleaner. What is the most likely reason?","opts":["The cleaner needs more time to dry before it looks shiny.","You may be using a cleaner that isn't right for that type of floor, or it's leaving a residue behind.","The floor is old and can never look clean again.","You should mop it two or three more times with the same cleaner until it shines."],"correct":1,"cat":"Skill","scored":true,"id":121},{"q":"A customer's home has both a marble floor and a wooden floor. Which is the safest approach?","opts":["Use the same all-purpose floor cleaner on both, since most cleaners work everywhere.","Use a strong acidic cleaner on the marble to make it shine, and a wet mop on the wood.","Use a pH-neutral cleaner on the marble and a barely-damp mop on the wood, since each material reacts differently to water and chemicals.","Only dry-dust both floors and avoid any liquid cleaning products entirely."],"correct":2,"cat":"Skill","scored":true,"id":122},{"q":"You are told to disinfect a kitchen counter, but the only product you have says \"cleaner\" on the label, not \"disinfectant.\" What should you do?","opts":["Use it anyway — cleaning and disinfecting mean the same thing.","Recognize it may only remove dirt, not kill germs, and check if a proper disinfectant is available or ask what to use.","Use twice as much of the same cleaner to make it stronger.","Skip disinfecting that day since you don't have the exact product."],"correct":1,"cat":"Skill","scored":true,"id":123},{"q":"You are cleaning a bathroom and notice a strong chemical smell from a drain cleaner someone else used earlier. What is the safest thing to do before starting?","opts":["Start cleaning immediately with your usual products.","Ventilate the room first (open a window or door) and avoid mixing any new chemicals into the air.","Add your own bleach-based cleaner to cover up the smell.","Ignore the smell since it will go away on its own."],"correct":1,"cat":"Skill","scored":true,"id":124},{"q":"A customer asks you to clean a chandelier hanging quite high above a dining table, and there's no stable ladder nearby. What should you do?","opts":["Stand on the dining table or a chair to reach it.","Skip that task, explain to the customer that you can't safely reach it without proper equipment, and suggest an alternative.","Use a long broom to knock the dust off from a distance.","Ask the customer to hold the chair steady while you climb on it."],"correct":1,"cat":"Skill","scored":true,"id":125},{"q":"You finish cleaning a living room with 10 minutes left in your booking, and everything already looks done. What's the best use of that time?","opts":["Sit and wait for the booking to officially end.","Do a final walk-through to check corners, surfaces, and details you might have missed.","Start a new task the customer didn't ask for, without checking with them.","Leave a few minutes early since the work looks finished."],"correct":1,"cat":"Skill","scored":true,"id":126},{"q":"Which of these is the correct general order for cleaning a room, from top to bottom?","opts":["Mop the floor, then dust the shelves, then wipe the windows.","Dust high surfaces and shelves first, then wipe surfaces, then vacuum or mop the floor last.","Vacuum the floor first, then dust the shelves so the dust settles on the clean floor.","It doesn't matter what order you do things in, as long as everything gets done eventually."],"correct":1,"cat":"Skill","scored":true,"id":127},{"q":"You spill a small amount of your cleaning product on a customer's rug by accident. What should you do first?","opts":["Rub it hard with a dry cloth immediately.","Blot it gently with a clean, damp cloth as soon as possible, rather than rubbing or scrubbing it.","Leave it to dry on its own and deal with it at the end.","Pour water all over the rug to dilute it completely."],"correct":1,"cat":"Skill","scored":true,"id":128},{"q":"A customer's instructions say to use only their own products, but their kitchen cleaner bottle appears to be empty. What should you do?","opts":["Use your own product instead without mentioning it.","Let the customer know their product is empty and ask how they'd like you to proceed.","Skip cleaning the kitchen for that visit.","Use plain water only, without asking anyone."],"correct":1,"cat":"Skill","scored":true,"id":129},{"q":"Which combination of cleaning chemicals should you never mix together?","opts":["Water and dish soap.","Bleach and ammonia-based cleaners.","Vinegar and water.","Baking soda and water."],"correct":1,"cat":"Skill","scored":true,"id":130},{"q":"You are cleaning a home with a newborn baby present. Which precaution matters most?","opts":["Use the strongest chemicals available to make sure everything is fully disinfected.","Choose milder products where possible, keep all chemicals sealed and out of reach, and ventilate the area.","Skip cleaning the baby's room entirely to avoid any risk.","Use scented sprays generously so the room smells fresh."],"correct":1,"cat":"Skill","scored":true,"id":131},{"q":"While vacuuming, you notice the vacuum is losing suction and making a straining noise. What should you do?","opts":["Keep pushing it harder since it will still work eventually.","Stop and check if the dust bag or bin is full, or something is stuck, since continuing could damage the machine.","Ignore the noise since vacuums often sound like that.","Switch it off and skip vacuuming for that visit without telling anyone."],"correct":1,"cat":"Skill","scored":true,"id":132},{"q":"A customer's expensive rug has instructions that say \"dry cleaning only,\" but you only have wet-cleaning tools with you. What should you do?","opts":["Use your wet-cleaning tools anyway, carefully.","Skip cleaning that rug and let the customer or your supervisor know, rather than risk damaging it.","Use a strong amount of water to make sure it's properly clean.","Try to dry it quickly with a hairdryer afterward."],"correct":1,"cat":"Skill","scored":true,"id":133},{"q":"Partway through a job, you realize you forgot to bring one of your usual cleaning tools. What is the best first step?","opts":["Skip that part of the cleaning silently.","Check if a safe substitute is available, or inform the customer or supervisor rather than pretending everything is fine.","Use whatever random product is under the customer's sink without checking what it is.","Rush through that task without the right tool and hope no one notices the quality difference."],"correct":1,"cat":"Skill","scored":true,"id":134},{"q":"You will live in company-provided housing together with other cleaners while working in Saudi Arabia, away from your own family. Which mindset will help you the most?","opts":["Expecting it to feel exactly like living at home with your own family.","Accepting that shared housing is part of this opportunity, and treating your housemates and the arrangement with respect.","Planning to complain to the company frequently until living arrangements change.","Avoiding all housemates and treating the accommodation as a temporary annoyance only."],"correct":1,"cat":"Lifestyle","scored":true,"id":135},{"q":"You get one day off every week, with no exceptions, even during busy periods. If you feel you deserve an extra day off one week, what is the right approach?","opts":["Simply not show up on a day you decide you need off.","Discuss it respectfully through the proper channel, and accept the standard policy if it can't be changed.","Convince other cleaners to also take an extra day off together.","Take the day off first, then explain the reason afterward."],"correct":1,"cat":"Lifestyle","scored":true,"id":136},{"q":"Some days you may have very few bookings, and you'll spend time in the van on standby waiting for the next job. What is the best attitude to have on a slow day like this?","opts":["Treat it as wasted time and ask to go home early.","Stay ready and available, since standby time is part of an on-call job, and more bookings can come at any moment.","Complain to the other cleaners about how unfair it is.","Use the time to look for other jobs on your phone."],"correct":1,"cat":"Lifestyle","scored":true,"id":137},{"q":"Customers rate your work after each booking, and these ratings affect your incentives. If a customer gives you a lower rating than you expected, what should you do?","opts":["Argue that the rating system is unfair and should be removed.","Reflect on what might have gone wrong, try to understand the feedback, and improve for the next booking.","Ignore it completely since one rating doesn't matter.","Stop putting in extra effort since ratings feel out of your control anyway."],"correct":1,"cat":"Lifestyle","scored":true,"id":138},{"q":"You will serve many different customers every day — some pleasant, some difficult and demanding. Which approach shows the strongest professional attitude?","opts":["Give your best effort only to customers who are polite to you.","Match a difficult customer's tone if they are rude to you first.","Stay consistently professional and give your best effort regardless of how demanding or difficult a customer is.","Ask to be reassigned away from any customer who seems demanding."],"correct":2,"cat":"Lifestyle","scored":true,"id":139},{"q":"Bookings can be either 2 hours or 4 hours long, and you won't always know in advance which type is next. Why does this matter for how you plan a job?","opts":["It doesn't matter — you should clean at the exact same pace regardless of the time given.","You should quickly judge the scope of work against the time given, and prioritize accordingly.","You should always assume it's a 4-hour job and slow down your pace.","You should ask the customer to shorten the job if it seems like too much work."],"correct":1,"cat":"Lifestyle","scored":true,"id":140},{"q":"Including travel between customers, your total working day can run 13 to 14 hours, even though only 8 of those hours are spent actually cleaning inside homes. What does this tell you about the role?","opts":["That most of the day will be idle time with nothing to do.","That the job requires real physical and mental stamina across a long day, not just the hours spent inside a home.","That the extra hours are a mistake that should be reported immediately.","That you can expect to finish work much earlier than 8 hours most days."],"correct":1,"cat":"Lifestyle","scored":true,"id":141},{"q":"During your 5-day training in Saudi Arabia, trainers will push you hard, expect fast learning, and focus heavily on speed, priorities, and following the exact cleaning process. What is the best way to approach this training?","opts":["Expect it to be relaxed since it's only training, not real work.","Push back on any part of training that feels too demanding.","Treat it seriously, follow instructions closely, and use it to build real speed and habits you'll rely on afterward.","Try to do things your own way if you already have some cleaning experience."],"correct":2,"cat":"Lifestyle","scored":true,"id":142},{"q":"Training focuses heavily on following the exact cleaning process (SOP) rather than doing things \"your own way,\" even if your own way also gets the house clean. Why might the company still insist on this?","opts":["Because the company doesn't trust any cleaner's judgment at all.","Because a consistent, tested process helps guarantee quality and speed across every customer and every cleaner, not just for you personally.","Because your own way is definitely wrong.","Because SOPs are only for people with no prior experience."],"correct":1,"cat":"Lifestyle","scored":true,"id":143},{"q":"After training, your first 10 customer ratings must average above 4.7 out of 5. If they don't, you go through retraining, and after 3 retrainings without improving, the job ends. How should a candidate think about this system before joining?","opts":["As an unfair system that shouldn't apply to genuine effort.","As a clear, fair standard to aim for, with real support (retraining) built in before any final decision is made.","As something to worry about only if it actually happens.","As a reason to do the minimum until the first 10 ratings are behind them."],"correct":1,"cat":"Lifestyle","scored":true,"id":144},{"q":"Your supervisor asks you to redo part of a job because it didn't fully meet the required standard. What is the best response?","opts":["Explain all the reasons it was difficult and argue it should be accepted as is.","Redo it properly without excuses, and ask what exactly needs to improve if it's unclear.","Redo it, but complain to other cleaners about the request afterward.","Do the minimum extra needed to avoid further comment."],"correct":1,"cat":"Lifestyle","scored":true,"id":145},{"q":"Partway through your time in this role, the company changes one of its cleaning procedures. What is the ideal reaction?","opts":["Continue using the old method since it worked fine before.","Learn and adapt to the new procedure, treating it as a normal part of doing the job well.","Follow the new procedure only when a supervisor is watching.","Push back and ask to keep doing it the old way."],"correct":1,"cat":"Lifestyle","scored":true,"id":146},{"q":"During training, a trainer corrects your technique in front of other trainees. What is the most professional reaction?","opts":["Feel embarrassed and stop trying as hard for the rest of training.","Accept the correction respectfully and apply it, since that's the purpose of training.","Argue that your original technique was fine.","Avoid that trainer for the rest of the program."],"correct":1,"cat":"Lifestyle","scored":true,"id":147},{"q":"A few cleaners you know are refusing to take certain bookings to pressure the company into a change they want. What should you do?","opts":["Join them, since it's safer to stay with the group.","Continue doing your job professionally, and raise any real concern through the proper channel instead of refusing work.","Refuse work quietly on your own, without telling anyone why.","Support them publicly but keep working normally yourself."],"correct":1,"cat":"Lifestyle","scored":true,"id":148},{"q":"You're running slightly behind schedule and the next customer is waiting. The current customer casually mentions one more small task they'd like done. What's the best approach?","opts":["Ignore the request since you're already behind schedule.","Quickly judge if it's reasonable to fit in, do it well if you can, and communicate honestly if you truly can't — rather than ignoring the customer.","Do it regardless of the impact on the next customer's booking.","Tell the customer you're too busy and end the booking immediately."],"correct":1,"cat":"Lifestyle","scored":true,"id":149},{"q":"You accidentally leave a customer's back door unlocked after finishing a job, and you're already on your way to the next booking when you remember. What should you do?","opts":["Continue to your next job since you're already running late.","Contact the customer or your supervisor immediately to inform them, even if it feels awkward.","Wait until your shift ends to mention it, since it's probably fine.","Say nothing unless someone asks you directly."],"correct":1,"cat":"SituationHandling","scored":true,"id":150},{"q":"Two customers on the same day give you almost identical, very specific complaints about how a certain area was cleaned. What does this most likely suggest?","opts":["Both customers happen to be equally difficult to please.","There may be a genuine gap in your technique for that specific task worth reviewing.","It's just a coincidence with no real meaning.","The customers are probably coordinating to complain unfairly."],"correct":1,"cat":"SituationHandling","scored":true,"id":151},{"q":"A customer's pet knocks over your cleaning bucket, spilling dirty water on their floor. What is your best first move?","opts":["Blame the pet to the customer and wait for them to clean it.","Clean up the spill right away and calmly let the customer know what happened.","Ignore it since it wasn't your fault.","Quietly mop it up without mentioning it at all."],"correct":1,"cat":"SituationHandling","scored":true,"id":152},{"q":"You realize partway through a booking that you skipped a step earlier to save time, and the customer hasn't noticed or said anything yet. What's the right move?","opts":["Say nothing since they haven't complained.","Go back and properly complete the step you skipped before finishing the booking.","Finish the booking and fix it only if the customer specifically complains.","Mention it to the customer but don't actually fix it."],"correct":1,"cat":"SituationHandling","scored":true,"id":153},{"q":"You're asked to clean a home, but the customer isn't there and has left no written instructions. There are clearly dirty dishes in the sink, along with general dust throughout. What should guide your first decision?","opts":["Random personal preference — start wherever feels easiest.","Common priority and visible impact — likely starting with kitchen hygiene, like the dishes, since it affects health and is highly visible.","Doing the least amount of work needed to say the job is done.","Waiting outside until the customer returns before starting anything."],"correct":1,"cat":"SituationHandling","scored":true,"id":154},{"q":"You realize, after leaving a booking, that you may have used the wrong (weaker) product on a stain the customer specifically asked about. What is the right next step?","opts":["Say nothing and hope the stain looks fine once fully dry.","Contact the customer or your supervisor to flag it, so it can be checked and fixed if needed.","Wait to see if the customer complains before doing anything.","Blame the product's label for being unclear, without following up further."],"correct":1,"cat":"SituationHandling","scored":true,"id":155},{"q":"A newer cleaner on your team asks you to cover part of their booking so they can leave early, without telling the supervisor. What should you do?","opts":["Agree quietly, since it's a personal favor between cleaners.","Decline to do it without supervisor approval, and suggest they raise it properly instead.","Agree, but only if they promise to return the favor later.","Report them without offering any explanation or chance to fix it themselves."],"correct":1,"cat":"SituationHandling","scored":true,"id":156},{"q":"You notice the customer seems visibly upset or stressed when you arrive, though they haven't said anything to you. What is the most professional approach?","opts":["Ask them directly and repeatedly what's wrong until they explain.","Proceed calmly and professionally with the booking, giving them space, and respond helpfully if they choose to say something.","Assume it's about your work and apologize preemptively for anything you might have done.","Leave early since the atmosphere feels uncomfortable."],"correct":1,"cat":"SituationHandling","scored":true,"id":157}];

module.exports = { QUESTIONS };
